import {validateRow} from './analytics/data-quality.js';
import {mean} from './analytics/stats.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const CHANNELS=['Instagram','Classroom Announcement','Posters','Discord','Remind','Email','Word of Mouth','Club Rush','Other'];
const input=(label,name,help='',type='number',required=false)=>`<label>${label}${required?' *':''}<input name="${name}" type="${type}" ${type==='number'?'min="0" max="10000000" step="1"':''} ${required?'required':''} ${type==='text'?'maxlength="150"':''}><span class="field-help">${help}</span></label>`;
const select=(label,name,values)=>`<label>${label}<select name="${name}"><option value="">Not provided</option>${values.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`;
export function promotionFields(){return `<fieldset class="channel-field"><legend>Promotion channels</legend><p class="field-help">Choose all that apply. Leave blank if unknown.</p><div class="channel-options">${CHANNELS.map(v=>`<label><input type="checkbox" name="channels" value="${v}"> ${v}</label>`).join('')}</div></fieldset>`}
export function meetingFields(){return `<p>Only date and attendance are required. Leave unknown values blank.</p><fieldset><legend>Meeting</legend><div class="form-grid">${input('Meeting name','name','For example: NBA Draft Debate.','text')}${input('Date','date','When the meeting happened.','date',true)}${select('Meeting type','type',['Presentation','Discussion','Interactive Activity','Workshop','Competition','Guest Speaker','Social','Other'])}${select('Meeting time','time',['Before School','Lunch','After school','Evening','Other'])}</div></fieldset><fieldset><legend>Attendance</legend><div class="form-grid">${input('Attendance','attendance','Total people who attended.','number',true)}${input('New members','new_members','People attending for the first time.')}${input('Returning members','returning_members','People who have attended before.')}</div><p class="member-warning" role="status"></p></fieldset><fieldset><legend>Promotion</legend>${promotionFields()}<div class="form-grid">${promotionTimingField()}${input('Instagram reach before meeting','reach','From Instagram Insights. Leave blank if your club does not use Instagram.')}${input('Signups before meeting','signups','People who expressed interest beforehand.')}</div></fieldset><details class="optional-fields"><summary>Optional: special event and notes</summary><div class="form-grid">${select('Special event','special_event',['Yes','No'])}<label>Notes<textarea name="notes" maxlength="1000" placeholder="Extra context, without personal student information"></textarea></label></div></details><details class="optional-fields"><summary>Advanced Retention Tracking</summary><p>Optional: use stable anonymous IDs to measure whether the same newcomers return. No names are needed.</p><label>Anonymous member IDs<input name="members" placeholder="M001;M002;M003"><span class="field-help">One ID per attendee, separated by semicolons.</span></label></details>`}
export function formRecord(form){const data=new FormData(form),raw=Object.fromEntries(data);raw.channels=data.getAll('channels');raw.promotion=raw.channels.join(' + ');return raw}
export function countWarning(raw){return raw.new_members!==''&&raw.returning_members!==''&&raw.new_members!=null&&raw.returning_members!=null&&Number(raw.new_members)+Number(raw.returning_members)!==Number(raw.attendance)?'New + returning members does not equal attendance. Your values will be kept, but excluded from member analysis until corrected.':''}
export function bindCountWarning(form){form.addEventListener('input',()=>{const box=form.querySelector('.member-warning');if(box)box.textContent=countWarning(formRecord(form))})}
export function dataChoices(){return `<section class="data-choices"><article class="card"><h2>Google Sheets</h2><p>Best for ongoing tracking with your officers.</p><a class="button" href="#sheets">Use Google Sheets →</a></article><article class="card"><h2>Excel</h2><p>Best for an offline spreadsheet.</p><a href="templates/clubpulse-template.xlsx" download>Download Excel template</a><button class="button upload-choice" data-format=".xlsx">Upload Excel</button></article><article class="card"><h2>CSV</h2><p>Best for quick, one-time imports.</p><a href="templates/clubpulse-template.csv" download>Download CSV template</a><button class="button upload-choice" data-format=".csv">Upload CSV</button></article></section><p class="data-minimum"><strong>What does ClubPulse need?</strong> Date + attendance. More columns unlock deeper insights. Replace the three fictional example rows with your own records.</p>`}
export function planExtraFields(){return `${input('Meeting name','name','A label for your plan.','text')}${input('Meeting date','date','For your planning notes; not a model input.','date')}${promotionTimingField()}`}
export function planningEvidence(rows,event){const fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:1});const signals=[];for(const [key,label]of [['type','Meeting format'],['time','Meeting time'],['promotion','Promotion channels']]){if(!event[key])continue;const matches=rows.filter(r=>r[key]===event[key]);signals.push({label,count:matches.length,text:matches.length?`${event[key]} averaged ${fmt(mean(matches.map(r=>r.attendance)))} attendees across ${matches.length} meetings. ${matches.length<3?'Too few examples for a reliable pattern.':'This association may overlap with other factors.'}`:`No recorded meetings used ${event[key]}. The forecast falls back to your recent average.`})}if(event.days_promoted_before!==''&&event.days_promoted_before!=null){const early=Number(event.days_promoted_before)>=3;const matches=rows.filter(r=>r.days_promoted_before!=null&&(r.days_promoted_before>=3)===early);signals.push({label:'Promotion timing',count:matches.length,text:matches.length>=3?`${matches.length} meetings promoted ${early?'3+':'0–2'} days ahead averaged ${fmt(mean(matches.map(r=>r.attendance)))} attendees. Timing is contextual evidence, not a numerical forecast input.`:'Record at least three meetings with similar promotion timing before interpreting a pattern.'})}return signals}
export function normalizePlan(raw){const row=validateRow({...raw,date:'2026-01-01',attendance:0});return {...raw,type:row.type,time:row.time,promotion:row.promotion,reach:row.reach,days_promoted_before:row.days_promoted_before}}

export function promotionTimingField(){return '<label>Promotion started<select name="days_promoted_before"><option value="">Not recorded</option><option value="0">Same day</option><option value="1">1 day before</option><option value="2">2–3 days before</option><option value="5">4–7 days before</option><option value="8">More than 1 week before</option></select><span class="field-help">Saved as approximately 0, 1, 2, 5 or 8 days. Use an exact number in your spreadsheet if known.</span></label>'}
